INSERT INTO `about_content` (`id`, `section`, `title`, `content`, `image_path`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'mission', 'Our Mission', 'RWVCA is to enhance collaboration among key stakeholders in the wood sector to collectively find solutions to the challenges that arise in the wood sector.', NULL, 3, 1, '2025-09-26 12:06:29', '2025-12-19 14:43:55'),
(2, 'vision', 'Our Vision', 'The vision of RWVCA is To become a strong representative of the wood value chain by serving the interests of  RWVCA members.', NULL, 4, 1, '2025-09-26 12:06:29', '2025-12-19 14:44:45'),
(3, 'objectives', 'Our Objectives', 'The objective of RWVCA is to:\r\n(a)	Advocate for its members on the issues they face that could negatively affect the development and growth of their businesses\r\n(b)	Ensure development and defend the interests of its members in the professional, economic, and social fields;\r\n(c)	To promote and improve the profession of all wood value chain;\r\n(d)	Training members and equipping them with useful information for the development of their profession;\r\n(e)	Promotion of partnership with various organizations, including donors, to seek markets for family members and support initiatives that propel RWVCA forward\r\n(f)	Promotion of social dialogue among members for all wood value chain;\r\n(g)	Create and improve relations with other associations that have the same vision on the national and international level;\r\n(h)	Organizing and attending trade fairs both nationally and internationally.', NULL, 5, 1, '2025-09-26 12:06:29', '2025-12-19 14:46:58');
INSERT INTO `ads` (`id`, `title`, `description`, `url`, `status`, `created_at`, `updated_at`) VALUES
(8, 'RRA–RWVCA Stakeholder Engagement Meeting on .........', 'On February 18, 2025, the Rwanda Wood Value Chain Association (RWVCA) held a strategic stakeholder meeting with the Rwanda Revenue Authority (RRA) to discuss pressing challenges faced by timber businesses in Rwanda.', 'ads/ads_1762941808.jpg', 'active', '2025-11-12 10:03:28', '2025-11-12 10:03:28'),
(9, '400 Skilled Carpenters Earn National Certification Through the Recognition of Prior Learning (RPL) Program', 'In a remarkable milestone for Rwanda’s skills development agenda, 400 skilled carpenters have officially earned their National Certification through the Recognition of Prior Learning (RPL) program.', 'ads/ads_1762942038.jpeg', 'active', '2025-11-12 10:07:18', '2025-11-12 10:07:18');
