(94, 182, 1, 'Dear Josiane, Could you please pass next week? thanks for your consideration.', '2026-07-03 07:16:14', '2026-07-03 07:16:14', 92, 'active'),
(95, 182, 74, 'Dear olga, you will tell me the day you will be available and i will come on that day.\r\nThank you', '2026-07-03 08:31:40', '2026-07-03 08:31:40', 94, 'active'),
(96, 182, 1, 'You are welcome to come any day next week, please just inform me before.', '2026-07-03 10:32:55', '2026-07-03 10:32:55', 95, 'active'),
