(102, 201, 1, 'Ok. Your request Permission is approved', '2026-07-22 07:16:29', '2026-07-22 07:16:29', NULL, 'active'),
(103, 202, 1, 'Dear Emmanuel\r\nPermission granted. Please go to the hospital and take care of your health. We wish you a quick recovery.\r\nThank you.', '2026-07-22 07:42:51', '2026-07-22 07:42:51', NULL, 'active'),
(104, 203, 1, 'Dear Emmanuel,\r\nThank you for the update and we wish you a speedy recovery. Please continue following the doctor\'s recommendations and focus on your recovery. We hope you will feel better soon. Take care and get well soon.\r\nKind regards, HR', '2026-07-22 14:01:15', '2026-07-22 14:01:15', NULL, 'active'),
