INSERT INTO `document_comments` (`id`, `document_id`, `user_id`, `parent_comment_id`, `comment_text`, `commented_at`) VALUES
(1, 2, 1, NULL, 'Dear all,\r\nPlease share your inputs to finalize our resolutions taken during the previous meeting. \r\nThanks', '2026-02-06 18:12:21'),
(2, 2, 2, NULL, 'Dear HR, \r\nMy input is for attendance ( to make it digital, by selecting staff to sign on attendance, and once staff are approved, you will be allowed to print out )\r\n\r\nThanks!\r\nDaniel', '2026-02-09 08:20:41'),
(3, 2, 5, NULL, 'Dear Olga,\r\nThank you for sharing the minutes. Everything has been clearly and accurately documented.', '2026-02-09 12:51:37'),
(4, 2, 1, 3, 'Thank you for the feedback.', '2026-02-09 13:13:44'),
(5, 2, 1, 2, 'Thank you for your comment.', '2026-02-09 13:14:17'),
(6, 5, 5, NULL, 'Dear Olga,\r\nThank you for sharing the draft.\r\nWhen you have a moment, please pass by my office so we can discuss it further.\r\nThank you', '2026-02-12 08:28:58'),
(7, 7, 5, NULL, 'check it i sent', '2026-02-12 09:56:11'),
(8, 8, 5, NULL, 'The format isn\'t open. Please check again', '2026-02-12 10:43:15'),
(9, 9, 6, NULL, 'Hello Claudine, \r\nPlease find attached the draft minutes for the meeting held between RWVCA and ABTP on 04 February 2O26, for your review and comments, ahead of finalization. The draft concept note will follow. \r\nThanks, and regards.', '2026-02-12 10:48:02'),
(10, 22, 1, NULL, 'Ndabona kameze neza ariko dufite ibwiriza ko logo ya RWVCA igomba kugendana niya PSF ndumva byakwitabwaho!', '2026-02-26 11:11:07'),
(11, 22, 2, 10, 'Ahubwo icyo nikibazo nshaka kubaza kuko hari ahantu ntarasobanukirwa kuko kuri gahunda cyangwa ibintu byose bya RWVCA sinzi niba buri cyo cyajyaho psf logo, kuko nejebundi ku modoka byarangiye dukoreshe logo imwe gusa ya RWVCA.', '2026-02-26 11:17:12'),
(12, 22, 6, NULL, 'Thank you Dany, ariko njye ndabina bishobotse website na location byajya inyuma hariya hari email ya association. Bikunze ukongeraho na gmail ya association.', '2026-02-27 09:06:56'),
(13, 22, 6, NULL, 'Ikindi ndabona hagombye kujyaho na personnal email y\' umuntu. Mbona ahandinariko bigenda.', '2026-02-27 09:08:38'),
(14, 26, 5, NULL, 'Ok.', '2026-03-11 10:24:35'),
(15, 27, 1, NULL, 'Dear ED,\r\nPlease find attached the leave plan proposal for employees in the Eastern Province Zone for your review and approval. The schedules for the remaining employees will be shared as soon as their individual plans are finalized. Thank you for your consideration.', '2026-03-16 07:17:44'),
(16, 41, 3, NULL, 'REQUEST  APRIL NOO 1', '2026-04-02 11:16:09'),
(17, 41, 5, 16, 'ok', '2026-04-02 15:03:05'),
(18, 41, 5, 16, 'ok', '2026-04-02 15:03:19'),
(19, 22, 7, NULL, 'Dear Daniel, nubwo nshyizeho comment to let, ariko ndabona hakwiye kujyaho n\'ifoto kuko uwayitora itariho ifoto yayiyitirira.', '2026-04-16 14:50:57'),
(20, 78, 2, NULL, 'Dear Emma,\r\nRegarding what ED mentioned, I have shared the G1PLUS + X PRINTER Internal Memo (Tablet) for your review and to proceed with the next steps.\r\nThanks.', '2026-08-18 17:14:24'),
(21, 79, 2, NULL, 'Dear Emma,\r\nRegarding what ED mentioned, I have shared the Concept note on RWVCA security surveillance system installation for your review and to proceed with the next steps.\r\nThanks.', '2026-08-18 17:19:31');
