INSERT INTO `member_products` (`product_id`, `product_name`, `company_name`, `description`, `phone`, `address`, `website_url`, `email`, `image1_url`, `image2_url`, `image3_url`, `is_active`, `created_at`, `updated_at`) VALUES
(2, 'Soft Nest sofa', 'Sofa Light Business Ltd', '7SEATERs SOFA WITH coffe table :Components: Frame assembled in marine boards(muba) or plywood, eucalyptus wood, pine wood, springs, and high-quality fabric material, high-quality mattress that lasts long. The client chooses the fabric material for covering to satisfy their color and texture needs. COFFEE TABLE made in Mdf with the top of white plastic marble, plastic marbles are in different colors. EXCEPTION: A client may choose furniture product design and materials according to his/her choice. Therefore, the Prices may change depending on specifications.', '0788689926', 'Kigali Rwanda - Kinamba / Remera', 'https://sofalight.rw/shop/product.php?pro=429', 'info@sofalight.rw', 'uploads/products/product_2_image1_69296fe53fe67.jpeg', 'uploads/products/product_2_image2_69296fe540037.jpeg', 'uploads/products/product_2_image3_69296fe540179.jpeg', 1, '2025-10-23 09:53:35', '2025-11-28 09:48:21'),
(5, 'Modern Wooden Kitchen', 'GITI BUYE ART Ltd', 'A Modern Wooden Kitchen features clean lines, smooth finishes, and a minimalist look that highlights the natural beauty of wood. It often uses sleek flat-panel cabinets in oak, walnut, or light timber, paired with neutral countertops like white quartz or black stone. Built-in appliances, soft LED lighting, and subtle hardware create a seamless, elegant, and contemporary space that feels warm, functional, and stylish.\r\n_______________________________________________________\r\nBest wood craft, furniture, wall wood, we make ur house look like paradise, book ur next appointment.', '+250788405447', 'Kigali, Rwanda - Kagarama/Kicukiro', 'https://www.instagram.com/gitibuyeartltd/', 'gitibuye@gmail.com', 'uploads/products/product_1764329321_image1_6929876948031.jpg', 'uploads/products/product_1764329321_image2_69298769480d8.jpg', 'uploads/products/product_1764329321_image3_6929876948122.jpg', 1, '2025-11-28 11:28:41', '2025-11-28 11:28:41');
