(2, 6, 'Nyabihu,  Coding Accademy', '<p>Participate in the Capacity Building Workshop for the Private Sector on Dual TVET. From 25 - 29 May 2026</p>', '2026-05-25', '2026-05-29', 4, 4, '2026', 1, 5, NULL, 'approved', 'verified', 'yes', '2026-05-25 13:49:41', 'verified', 'yes', '2026-05-25 14:05:24', NULL, '2026-05-25 13:39:48', '2026-05-25 14:05:24', 6, '', 'stamp_with_signature'),
(3, 6, 'Rwamagana - Nyanza - Kigali - Rwamagana', 'Dear HR,&nbsp;<div><br></div><div>I kindly request a mission order to participate in the study tour organized by ICRAF, on 11 June 2026. The study tour aims to introduce and connect PFMUs Cooperatives with Ultimate Forest Company for market linkage.&nbsp;</div><div><br></div><div>Route: Rwamagana - Nyanza - Kigali - Rwamagana.</div><div><br></div><div>Thank you for your consideration.&nbsp;</div><div><br></div><div><br></div>', '2026-06-11', '2026-06-11', 1, 1, '2026', 1, 5, NULL, 'verified_by_hr', 'verified', 'yes', '2026-06-10 12:39:52', 'pending', NULL, NULL, NULL, '2026-06-10 09:27:01', '2026-06-10 12:39:52', 6, '', 'no'),
(4, 2, 'Rwamagana - Nyanza - Kigali - Rwamagana', '<span style=\"color: rgb(68, 68, 68);\">Dear HR,&nbsp;</span><div><br style=\"color: rgb(68, 68, 68);\"><span style=\"color: rgb(68, 68, 68);\">I kindly request a mission order to participate in the study tour organized by ICRAF, on 11 June 2026. The study tour aims to introduce and connect PFMUs Cooperatives with Ultimate Forest Company for market linkage.&nbsp;</span></div><div><br style=\"color: rgb(68, 68, 68);\"><span style=\"color: rgb(68, 68, 68);\">Route: Rwamagana - Nyanza - Kigali - Rwamagana.</span></div><div><br style=\"color: rgb(68, 68, 68);\"><span style=\"color: rgb(68, 68, 68);\">Thank you for your consideration.&nbsp;</span><!--EndFragment--> </div>', '2026-06-11', '2026-06-11', 1, 1, '2026', 1, 5, NULL, 'verified_by_hr', 'verified', 'yes', '2026-06-10 12:38:45', 'pending', NULL, NULL, NULL, '2026-06-10 10:23:42', '2026-06-10 12:38:45', 2, '', 'no'),
(5, 116, 'KIGALI,GAHANGA', 'The purpose of this mission is to travel to the RWVCA headquarter in Gahanga,Kigali,to collect a laptop that will support my daily work as membership officer at Nyagatare.The latop will enhance data managament,reporting,communication,and the preparation of daily,weekly,monthly,quartely and annual reports,enabling me to provide accurate and timely information that supports organizational decision making and performance monitoring', '2026-06-12', '2026-06-12', 1, 1, '2026', 1, 5, NULL, 'approved', 'verified', 'yes', '2026-06-11 11:58:52', 'verified', 'yes', '2026-06-11 14:09:34', NULL, '2026-06-11 10:15:48', '2026-06-11 14:09:34', 116, '', 'stamp_with_signature'),
(6, 6, 'Rwanda Coding Academy, Nyabihu Doistrict', 'To participate in consultation workshop on Dual TVET implementation.', '2026-06-22', '2026-06-25', 4, 4, '2026', 1, 5, NULL, 'approved', 'verified', 'yes', '2026-06-23 12:06:22', 'verified', 'yes', '2026-06-24 10:38:31', NULL, '2026-06-23 07:35:33', '2026-06-24 10:38:31', 6, '', 'stamp_with_signature'),
(8, 7, 'NYANZA DISTRICT', '<span style=\"color:black\">To participate in the study tour and Capacity Development Needs Assessment&nbsp;</span><!--EndFragment--><span style=\"color:black\">scheduled to take place on <b>Tuesday, 30 June 2026</b>.</span><!--EndFragment-->', '2026-06-30', '2026-06-30', 1, 1, '2026', 1, 5, NULL, 'approved', 'verified', 'yes', '2026-06-29 09:21:04', 'verified', 'yes', '2026-07-02 06:38:13', NULL, '2026-06-29 08:44:42', '2026-07-02 06:38:13', 7, '', 'stamp_with_signature'),
