(11, 'Election report: Western Province', 'Activity', '<p>Election report for RWVCA representatives at Provincial, district and value chain platforms, conducted on 20 February 2026 at Romantic Hotel in Karongi, Western Province. </p>', '2026-02-20', '2026-02-20', 6, '2026-02-24 08:06:37', '2026-02-24 08:06:37', '10:00:00', '14:30:00', 'Karongi District'),
(12, 'PRELIMINARY ELECTION REPORT', 'Activity', '<p>Dear ED,</p><p><br></p><p>Allow me to present to you the preliminary report from the election held on 20/02/2026.</p><p><br></p><p>Thanks.</p>', NULL, NULL, 7, '2026-02-24 09:36:52', '2026-02-24 09:36:52', NULL, NULL, 'FIELD'),
(13, 'KIMIRONKO ICPCs', 'Weekly', '<p>Week Report from 23 to 28 February 2026</p>', '2026-02-23', '2026-02-28', 101, '2026-03-02 07:29:00', '2026-03-02 07:29:00', '17:32:00', '05:32:00', 'KIMIRONKO ICPCs'),
(14, 'KIMIRONKO ICPCs', 'Monthly', '<p>Month Report from Kimironko Daily Activities </p>', '2026-02-01', '2026-02-28', 101, '2026-03-02 07:32:59', '2026-03-02 07:32:59', '13:30:00', '10:35:00', 'KIMIRONKO ICPCs'),
(15, 'WEEKLY REPORT', 'Weekly', '<p><br></p>', '2026-02-23', '2026-02-28', 78, '2026-03-02 07:52:37', '2026-03-02 07:52:37', '09:35:00', '09:36:00', 'KIGALI OFFICE , GASHYUSHYA FIELED'),
(16, 'Monthly report', 'Monthly', '<p><strong>Hello there! good day ! this is a monthly report  of february, i hope you receive it well thank you.  Icpcs Gashyushya and other....</strong></p>', '2026-02-01', '2026-02-28', 78, '2026-03-02 08:03:18', '2026-03-02 08:03:18', '09:56:00', '09:56:00', 'KIGALI OFFICE , GASHYUSHYA FIELD'),
(17, 'Monthly Management Meeting Resolutions', 'Monthly', '<p class=\"ql-align-justify\"><strong><u>Mgt Meeting Resolutions (date: 02/03/2026)</u></strong></p><p class=\"ql-align-justify\">1.&nbsp;&nbsp;&nbsp;All monthly priorities, planning and reporting must be uploaded directly to both the internal management system and Google Drive.</p><p class=\"ql-align-justify\">2.&nbsp;&nbsp;&nbsp;The Project Coordinator is tasked with reviewing the strategic plan developed by Lenja. This is essential to ensure alignment with upcoming projections and the ongoing studies being conducted by Dr. Yassid.</p><p class=\"ql-align-justify\">3.&nbsp;&nbsp;&nbsp;The presentation of audit report is scheduled as: on 9<sup>th</sup> March for ED, 11<sup>th</sup> March for Audit committee, 13<sup>th</sup> March for EXCO, 20<sup>th</sup> March for General Assembly</p><p class=\"ql-align-justify\">4.&nbsp;&nbsp;&nbsp;A site visit to Rusizi ICPC is scheduled for 23 March 2026. During this mission, the team will also visit Nyamasheke, Rutsiro, and Ngororero.</p><p class=\"ql-align-justify\">5.&nbsp;&nbsp;&nbsp;All Members interested in joining the RWVCA Showroom must submit and installer their product no later than the end of this week</p><p class=\"ql-align-justify\">6.&nbsp;&nbsp;&nbsp;The showroom banner design must be finalized and ready for printing immediately upon the project\'s commencement</p><p class=\"ql-align-justify\">7.&nbsp;&nbsp;&nbsp;Membership Project was requested to build the platform of furniture production members in order to be ready prepared for the Minicom’s Made in Rwanda project </p><p class=\"ql-align-justify\">8.&nbsp;&nbsp;&nbsp;The Project Coordinator is directed to visit (Public, Private, &amp; NGOs) to secure new partnerships, sponsorships, and funding for project activities.IT was requested to make sure the security of system and website</p><p class=\"ql-align-justify\">9.&nbsp;&nbsp;&nbsp;All staff are informed of the new project regarding Insurance Access for our members. RWVCA plans to collaborate with Old Mutual Rwanda for this service.</p>', '2026-03-02', '2026-03-02', 1, '2026-03-03 07:49:17', '2026-03-03 07:49:17', '14:00:00', '17:05:00', 'RWVCA Office'),
