(1, 'Request for Vehicle for Field Monitoring', '<!--StartFragment--><p data-start=\"119\" data-end=\"139\" class=\"PDq2pG_selectionAnchorContainer\">Dear Logistic,<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\r\n<p data-start=\"141\" data-end=\"249\">I would like to kindly request a vehicle to facilitate field monitoring activities in <strong data-start=\"227\" data-end=\"248\">Kicukiro District</strong></p>\r\n<p data-start=\"251\" data-end=\"341\">Your support in arranging transportation for this assignment would be greatly appreciated.</p><p data-start=\"251\" data-end=\"341\"><br></p>\r\n<p data-start=\"343\" data-end=\"419\">Thank you for your assistance!</p><!--EndFragment-->', '2026-07-14 09:00:00', '2026-07-14 11:30:00', 'Official Duty', NULL, '2026-07-15', 1, 4, 7, NULL, 7, 'pending', 'pending', 7, '2026-07-14 14:16:08', NULL, NULL, NULL, NULL, NULL, NULL, 'no', 'verification_process', NULL, NULL, NULL, 'pending', NULL, NULL, 'Okay. I will notify the driver.', NULL, NULL, NULL, 'Okay. I will notify the driver.', NULL, NULL, NULL, NULL, NULL, '2026-07-14 13:48:24', '2026-07-17 11:06:53'),
(2, 'Request for Transport Facilitation', 'Dear logistic ,<div>I would like to kindly request transport facilitation (a car) to enable me to travel to the Airtel Head Office to handle the internet-related issues.<!--EndFragment-->\r\n    </div><div>&nbsp;&nbsp;</div><div>Thanks for understanding!</div>', '2026-07-16 16:15:00', '2026-07-16 17:15:00', 'Official Duty', NULL, '2026-07-16', 1, 4, 7, NULL, 7, 'pending', 'pending', 7, '2026-07-16 14:17:42', NULL, NULL, NULL, NULL, NULL, NULL, 'no', 'authorized', NULL, NULL, NULL, 'pending', NULL, NULL, 'Okay. verified.', NULL, NULL, NULL, 'Okay. verified.', NULL, NULL, NULL, 5, '2026-07-17 15:36:14', '2026-07-16 14:16:06', '2026-07-17 13:36:14'),
(3, 'Meeting with Sammuel, Suis Contact.', '<div>Reason: Discussing possible institutional partnership.&nbsp;</div><div>Time 2:00 Pm</div><div>Venue: Kimihurura&nbsp;</div>', '2026-07-17 13:30:00', '2026-07-17 16:00:00', 'Official Duty', NULL, '2026-07-17', 1, 6, 7, NULL, 7, 'pending', 'pending', 7, '2026-07-17 08:12:43', NULL, NULL, NULL, NULL, NULL, NULL, 'no', 'authorized', NULL, NULL, NULL, 'pending', NULL, NULL, 'Okay. Verified.', NULL, NULL, NULL, 'Okay. Verified.', NULL, NULL, NULL, 5, '2026-07-17 15:04:59', '2026-07-17 08:10:15', '2026-07-17 13:36:01'),
(4, 'Gusaba kujya mu Kagera garage.', 'Ndasaba kumenesha amavuta ibiro metero byarangiye,&nbsp;<div>murakoze.</div>', '2026-07-20 09:23:00', '2026-07-20 05:23:00', 'Other', 'RAI905C', '2026-07-20', 6, 102, 7, 5, 7, 'verified', 'pending', 7, '2026-07-21 07:03:06', '2026-07-21 07:03:06', NULL, NULL, NULL, NULL, NULL, 'no', 'verification_process', NULL, NULL, NULL, 'pending', NULL, NULL, 'Okay. wagenda kumenesha amavuta. mvuganye na Claude ambwiyeko nibasoza bagukorera fagitire noneho ukayimwoherereza.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-20 07:25:05', '2026-07-21 07:03:06'),
(5, 'Gusaba ikinamba', 'Gusaba ikinamba imodoka prac RAI905C&nbsp;', '2026-07-20 09:39:00', '2026-07-20 11:39:00', 'Car Wash', NULL, '2026-07-20', 6, 102, 7, 5, 7, 'verified', 'pending', 7, '2026-07-20 07:41:40', '2026-07-20 07:41:40', NULL, NULL, NULL, NULL, NULL, 'no', 'authorized', NULL, NULL, NULL, 'pending', NULL, NULL, 'ok. Ugende ariko ujye ku kinamba gishyashya i Nyanza.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5, '2026-07-20 12:05:53', '2026-07-20 07:39:24', '2026-07-20 10:05:53'),
(6, 'KUJYANA IMODOKA PIKUP RAE 905C MU KINAMBA', 'Kujyana imodoka mukinamba', '2026-07-27 15:07:00', '2026-07-27 17:59:00', 'Car Wash', NULL, '2026-07-27', 6, 103, 7, 5, 7, 'verified', 'pending', 7, '2026-07-28 09:08:53', '2026-07-28 09:08:53', NULL, NULL, NULL, NULL, NULL, 'no', 'verification_process', NULL, NULL, NULL, 'pending', NULL, NULL, 'Jonh wajya kogesha imodoka.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-27 10:08:42', '2026-07-28 09:08:53'),
