(9, 'RAI905C', 'Gusaba ikinamba&nbsp;', '2026-08-10 09:21:00', '2026-08-10 11:21:00', 'Car Wash', NULL, '2026-08-10', 6, 102, 7, 5, 7, 'verified', 'pending', 7, '2026-08-10 07:22:26', '2026-08-10 07:22:26', NULL, NULL, NULL, NULL, NULL, 'no', 'verification_process', NULL, NULL, NULL, 'pending', NULL, NULL, 'Verified.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-10 07:21:22', '2026-08-10 07:22:26'),
(10, 'Request for Transportation for Field Monitoring', '<!--StartFragment--><p class=\"isSelectedEnd\">Good morning Madam ED,</p><p class=\"isSelectedEnd\">I would like to request transportation support to facilitate field monitoring activities in the Gasabo area, specifically at Kimironko and Gashyushya ICPCs Your support in providing transportation would help us conduct the monitoring activities effectively and on time.</p><p class=\"isSelectedEnd\">Thank you for your support and consideration.</p><!--EndFragment-->', '2026-08-11 10:33:00', '2026-08-11 14:00:00', 'Official Duty', NULL, '2026-08-11', 3, 4, 7, 5, 7, 'verified', 'pending', 7, '2026-08-11 08:25:03', '2026-08-11 08:25:03', NULL, NULL, NULL, NULL, NULL, 'no', 'authorized', NULL, NULL, NULL, 'pending', NULL, NULL, 'Verified.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5, '2026-08-12 11:56:31', '2026-08-11 08:23:44', '2026-08-12 09:56:31'),
(11, 'Carwash prac RAI905C', 'Ndasaba kogesha imodoka ejo yanduye cyane', '2026-08-12 09:31:00', '2026-08-12 11:25:00', 'Car Wash', NULL, '2026-08-12', 6, 102, 7, 5, 7, 'verified', 'pending', 7, '2026-08-12 07:39:28', '2026-08-12 07:39:28', NULL, NULL, NULL, NULL, NULL, 'no', 'verification_process', NULL, NULL, NULL, 'pending', NULL, NULL, 'Okay. Verified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-12 07:32:06', '2026-08-12 07:39:28'),
(12, 'To request a vehicle for official duties', 'Dear Logistics,&nbsp;&nbsp;<div>I hereby request a vehicle for official duties to visit Pergamon Company in Remera Kisimenti for a market survey on the POS/EBM machine. After that, I will proceed to the Starlink office at Kicukiro Centre to seek a quotation for their internet service. I will be accompanied by Emmy (Membership Coordinator) for this market survey.&nbsp;&nbsp;</div><div><br></div><div>Thanks.&nbsp;&nbsp;</div>', '2026-08-14 14:00:00', '2026-08-14 17:00:00', 'Official Duty', NULL, '2026-08-14', 1, 2, 7, 5, 7, 'verified', 'pending', 7, '2026-08-14 10:16:25', '2026-08-14 10:16:25', NULL, NULL, NULL, NULL, NULL, 'no', 'verification_process', NULL, NULL, NULL, 'pending', NULL, NULL, 'Okay.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-14 10:00:41', '2026-08-14 10:16:25'),
(13, 'Request a vehicle for official duties', '<!--StartFragment--><span style=\"background-color: rgb(248, 249, 250);\">Dear Logistics,&nbsp;&nbsp;</span><div>I hereby request a vehicle for official duties to visit Pergamon Company in Remera Kisimenti for a market survey on the POS/EBM machine.</div><!--EndFragment-->', '2026-08-18 10:30:00', '2026-08-18 12:00:00', 'Official Duty', NULL, '2026-08-18', 1, 2, 7, 5, 7, 'verified', 'pending', 7, '2026-08-18 08:23:14', '2026-08-18 08:23:14', NULL, NULL, NULL, NULL, NULL, 'no', 'verification_process', NULL, NULL, NULL, 'pending', NULL, NULL, 'okay.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-18 08:21:42', '2026-08-18 08:23:14');
INSERT INTO `special_requisitions` (`id`, `title`, `description`, `start_time`, `end_time`, `type`, `type_other`, `date`, `department_id`, `prepared_by`, `sended_to`, `executive_id`, `coordinator_id`, `coordinator_verification_status`, `executive_verification_status`, `verified_by`, `verified_at`, `coordinator_verified_at`, `coordinator_signature`, `approved_by`, `approved_at`, `executive_signature`, `executive_approved_at`, `ed_signature_and_stamp`, `status`, `rejection_reason`, `reason`, `viewer_id`, `viewer_status`, `viewer_comment`, `viewed_at`, `comment`, `reverted_at`, `reverted_by`, `reversion_reason`, `verification_comment`, `approval_comment`, `rejected_at`, `rejected_by`, `authorized_by`, `authorized_at`, `created_at`, `updated_at`) VALUES
(14, 'Car wash prac RAI905C', 'Ndasaba kogesha mukindi kinamba bagapfubura kuko imaze igihe tioga ngo icye neza!, nkaba nasabaga ko mwampa uburenganzira tukayijyana ahandi bayoza neza.<div>Murakoze.</div>', '2026-08-18 13:15:00', '2026-08-18 15:30:00', 'Car Wash', NULL, '2026-08-18', 6, 102, 7, 5, 7, 'pending', 'pending', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'no', 'reverted', NULL, NULL, NULL, 'pending', NULL, NULL, 'Kosora message yawe wanditse ntabwo ivugitse neza. Saba ko wajya mu kinamba cya kicukiro centere kugirango bayoze neza kurushaho kuberako ikinamba kitwegereye hari ibyo kitabasha kunoza kubera ko bafite ibikoresho bishya, hanyuma ubutaha izogerezwa ku kinamba cya bugufi kuko izaba idafite umwanda mwinshi. Urebe uburyo message igaragazamo ikinyabupfura kuko nakiriya kiroza ku rwego rwacyo ntabwo twakoresha ijambo gupfubura, Murakoze.', '2026-08-18 10:09:41', 7, 'Kosora message yawe wanditse ntabwo ivugitse neza. Saba ko wajya mu kinamba cya kicukiro centere kugirango bayoze neza kurushaho kuberako ikinamba kitwegereye hari ibyo kitabasha kunoza kubera ko bafite ibikoresho bishya, hanyuma ubutaha izogerezwa ku kinamba cya bugufi kuko izaba idafite umwanda mwinshi. Urebe uburyo message igaragazamo ikinyabupfura kuko nakiriya kiroza ku rwego rwacyo ntabwo twakoresha ijambo gupfubura, Murakoze.', NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-18 09:12:16', '2026-08-18 10:09:41'),
(15, 'Car wash prac RAI905C', 'Gusaba kogesha kicukiro center kuko hari ibikoresho bafite hano hafi badafite kungirango imodoka yoge neza hanyuma, hanyuma ubutaha tuzogeshe hano bugufi inyanza, murakoze.', '2026-08-18 13:18:00', '2026-08-18 15:18:00', 'Car Wash', NULL, '2026-08-18', 6, 102, 7, 5, 7, 'verified', 'pending', 7, '2026-08-18 11:54:04', '2026-08-18 11:54:04', NULL, NULL, NULL, NULL, NULL, 'no', 'verification_process', NULL, NULL, NULL, 'pending', NULL, NULL, 'Okay. Verified.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-18 11:18:32', '2026-08-18 11:54:04'),
(16, 'To request vehicle', 'Dear ED,<div><!--StartFragment-->We are pleased to write to you to kindly request a vehicle to transport RWVCA materials to the Expo organized by PSF Eastern Province.&nbsp;<!--EndFragment--></div>', '2026-08-19 13:40:00', '2026-08-19 20:30:00', 'Official Duty', NULL, '2026-08-19', 1, 7, 7, 5, 7, 'verified', 'pending', 7, '2026-08-19 11:27:01', '2026-08-19 11:27:01', NULL, NULL, NULL, NULL, NULL, 'no', 'authorized', NULL, NULL, NULL, 'pending', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5, '2026-08-19 15:04:33', '2026-08-19 11:26:43', '2026-08-19 13:04:33'),
(17, 'Prac RAI905C request car wash', 'Mwaramutse neza!,<div>Ndabasaba kujya kogesha kicukiro center, imodoka bakayoza neza kuberako hari ibikoresho bafite hariya turikogesha badafite,&nbsp;</div><div>Murakoze.</div>', '2026-08-24 09:08:00', '2026-08-24 11:30:00', 'Car Wash', NULL, '2026-08-24', 6, 102, 7, 5, 7, 'verified', 'pending', 7, '2026-08-24 07:12:46', '2026-08-24 07:12:46', NULL, NULL, NULL, NULL, NULL, 'no', 'verification_process', NULL, NULL, NULL, 'pending', NULL, NULL, 'okay.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-24 07:09:05', '2026-08-24 07:12:46');
