INSERT INTO `tickets` (`id`, `title`, `description`, `status`, `priority`, `assigned_to`, `created_by`, `category`, `attachments`, `created_at`, `updated_at`, `resolved_at`) VALUES
(3, 'Call', 'I want your support in my office please', 'closed', 'urgent', 2, 5, 'technical', '', '2026-02-09 11:25:18', '2026-02-11 11:53:52', '2026-02-11 11:53:52'),
(5, 'Updates on the new system', 'Please assist me for the system issue', 'closed', 'medium', 2, 6, 'technical', '', '2026-02-09 11:32:25', '2026-02-11 11:53:36', '2026-02-11 11:53:36'),
(6, 'Request requisition', 'Dear Emmy provide request for transport   here', 'open', 'medium', 7, 3, 'other', '', '2026-02-09 15:09:22', '2026-02-09 15:09:22', NULL),
(7, 'Review together the list of election participant per district', 'Dear Emmanuel and Gloriose \r\nPlease come into my office. I want to revise the list together. \r\nThanks', 'open', 'medium', 6, 5, 'general', '', '2026-02-10 09:03:06', '2026-02-10 09:03:06', NULL),
(13, 'Request for Vehicle', 'Dear Logistic, \r\nI am writing to formally request a vehicle for meet with the lawyer (Avoka) and deliver documents requested by the Court. I will meet with him at Nyamirambo Court today at 4:00 PM.\r\nI am waiting your feedback. Thank you', 'resolved', 'high', 7, 1, 'general', '', '2026-02-10 14:57:30', '2026-02-10 14:59:47', '2026-02-10 14:59:47'),
(15, 'Prepare an request for MINEDUC contract extension', 'Dear Olga,\r\nI hope you are doing well. Could you plan to prepare a letter to MINEDUC for a contract extension by tomorrow? \r\nPlease put it in your priorities. Thanks', 'open', 'urgent', 1, 5, 'general', '', '2026-02-10 16:16:44', '2026-02-10 19:07:18', NULL),
(16, 'Desktop Computer Issue', 'Dear Emmy,\r\n\r\nI hope you are doing well.\r\n\r\nAttached below are the details of the desktop computer issue. As I previously informed you, the computer was working at the time I handed it over. However, during the return process, I found that it was no longer working. You also mentioned earlier that the PC was not functioning.\r\n\r\nThe issue appears to be caused by the computer not detecting the disk that contains the operating system. This indicates that the device requires technical maintenance or attention from the person in charge of IT maintenance.\r\n\r\nThank you for your understanding.\r\n\r\nKind regards,\r\nDaniel', 'resolved', 'high', 7, 2, 'technical', '1770733040_e3dd9fc2ec0b65b2.jpeg|WhatsApp Image 2026-02-10 at 16.04.22.jpeg', '2026-02-10 16:17:20', '2026-03-18 17:41:42', '2026-03-18 17:41:42'),
(17, 'System Errors', 'Dear Dany,\r\nI hope you are doing well. Kindly check those errors and resolved as soon as possible.\r\nRegards', 'closed', 'urgent', 2, 5, 'general', '1770884142_e692e3eefcd10570.png|Errors.png', '2026-02-12 10:15:42', '2026-02-13 15:32:54', '2026-02-13 15:32:54'),
(20, 'Laptop cleaning', 'Dear ED,  \r\nI would like to request a simple cleaning of your personal computer in your office.  \r\n\r\nKind regards', 'closed', 'high', 5, 2, 'technical', '', '2026-02-13 15:02:42', '2026-02-13 15:30:42', '2026-02-13 15:30:42'),
(21, 'Assistance Needed – Portal Email Notification & Printing Issue', '<p>I’m facing an issue with the portal system. I’m not receiving the email notifications for the tasks assigned to me in the portal, Additionally, I’m experiencing a problem with the printing system.</p><p>please assist me in resolving them </p><p>thanks !</p><p><br></p><p>Regards!, </p><p>claudine/Assistant to ED  </p>', 'closed', 'medium', 2, 4, 'general', '', '2026-03-04 13:45:40', '2026-07-31 10:31:18', '2026-07-31 10:31:18'),
(23, 'weekly report', '<p><br></p>', 'closed', 'medium', 114, 72, 'finance', '1772879711_81c4d0687e15f9ab.pdf|GAATSIBO MONTHLY REPORT FOR FEBRUARY 2026.pdf', '2026-03-07 12:35:11', '2026-03-11 18:27:49', '2026-03-11 18:27:49'),
(24, 'Please help me to set the remaining annual leave for the last year 2025 in this system (My expected balance equal to 9 days)', '<p><br></p>', 'closed', 'medium', 2, 3, 'general', '', '2026-04-08 10:16:13', '2026-04-09 09:40:34', '2026-04-09 09:40:34'),
(25, 'Request for a vehicle', '<p>Helloooo, imodoka iri available ngo njye kurukiko?</p>', 'open', 'medium', 7, 1, 'general', '', '2026-05-05 13:34:50', '2026-05-05 16:47:23', NULL),
(27, 'Follow-up the iPad issue', '<div>Dear Danny.</div><div><br></div><div>Good morning.</div><!--StartFragment-->As you know, the iPad from Rusizi developed a problem and you requested that it be sent so you could assess the situation. That issue coincided with another one from Gatsibo. I would like to request you to help us present to the Director the way forward, because this is delaying the work. If it requires installing the EBM system on a laptop and then purchasing an external printer, that could also be a possible solution, and you could provide guidance on that.<!--EndFragment--><div><br></div><div>Thank you.</div>', 'closed', 'high', 2, 7, 'technical', '', '2026-06-15 09:39:42', '2026-07-31 10:29:51', '2026-07-31 10:29:51'),
(28, 'To remind', '<!--StartFragment--><p>Dear Daniel,</p><p>As HR has already showed us a guidance regarding the preparation of requirements for purchasing the security camera, I would like to remind you that the only pending things is the concept note, which is required for submission to Procurement team. We had already gathered the preliminary pricing information together. At your earliest convenience, please finalize the concept note so that we can proceed with the subsequent procedures.</p><p>Thank you for your cooperation.</p><!--EndFragment-->', 'in_progress', 'high', 2, 7, 'technical', '', '2026-07-31 09:06:10', '2026-07-31 10:30:38', NULL),
(29, 'request a support', 'Dear IT, please come to help with my laptop', 'open', 'urgent', 2, 1, 'technical', '', '2026-08-05 10:58:12', '2026-08-05 10:58:12', NULL);
