-- Structure for view `v_report_recipients`
--
DROP TABLE IF EXISTS `v_report_recipients`;

CREATE ALGORITHM=UNDEFINED DEFINER=`rwvcaorg`@`localhost` SQL SECURITY DEFINER VIEW `v_report_recipients`  AS SELECT `rr`.`report_id` AS `report_id`, `rr`.`recipient_type` AS `recipient_type`, `rr`.`recipient_id` AS `recipient_id`, CASE `rr`.`recipient_type` WHEN 'user' THEN `u`.`names` WHEN 'department' THEN `d`.`name` AS `end` END FROM ((`report_recipient` `rr` left join `users` `u` on(`rr`.`recipient_type` = 'user' and `rr`.`recipient_id` = `u`.`id`)) left join `department` `d` on(`rr`.`recipient_type` = 'department' and `rr`.`recipient_id` = `d`.`id`)) ;

